<h3 class="mb-4">المتابعة المالية</h3><div class="row g-3 mb-4"><?php foreach([['إجمالي الخدمات',$summary['gross_amount'],'primary'],['المحصّل',$summary['net_collected'],'success'],['عمولة المنصة',$summary['commission_amount'],'info'],['مستحق مقدمي الخدمة',$summary['provider_net_amount'],'warning']] as $c): ?><div class="col-md-3"><div class="card p-3"><div class="small text-muted"><?= e($c[0]) ?></div><div class="fs-5 fw-bold text-<?= $c[2] ?>"><?= number_format((float)$c[1],2) ?></div></div></div><?php endforeach; ?></div><div class="alert alert-info">موظف المنصة يطّلع على العمليات المالية حسب صلاحياته، ولا يملك إعدادات النظام العامة.</div><div class="table-responsive"><table class="table table-hover bg-white"><thead><tr><th>الفاتورة</th><th>الطلب</th><th>العميل</th><th>المقدم</th><th>الإجمالي</th><th>العمولة</th><th>الصافي</th><th>المدفوع</th><th>الحالة</th><?php if($canPayout): ?><th>تحويل</th><?php endif; ?></tr></thead><tbody><?php foreach($invoices as $i): ?><tr><td><?= e($i['invoice_number']) ?></td><td><?= e($i['request_number']) ?></td><td><?= e($i['customer_name']) ?></td><td><?= e($i['provider_name']??'—') ?></td><td><?= number_format($i['total_amount'],2) ?></td><td><?= number_format($i['commission_amount'],2) ?></td><td><?= number_format($i['provider_net'],2) ?></td><td><?= number_format($i['paid_amount'],2) ?></td><td><?= statusBadge($i['payment_status']) ?></td><?php if($canPayout): ?><td>من لوحة الإدارة</td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div>